"""Structured finding contract emitted by rule reasoner."""

from __future__ import annotations

from enum import Enum
from typing import Any

from pydantic import BaseModel, Field


class Severity(str, Enum):
    """Categorical severity ranking for detected vulnerabilities."""

    CRITICAL = "CRITICAL"
    HIGH = "HIGH"
    MEDIUM = "MEDIUM"
    LOW = "LOW"
    INFORMATIONAL = "INFORMATIONAL"


class Finding(BaseModel):
    """Structured security finding record generated by deterministic rule matches."""

    finding_id: str = Field(..., description="Unique finding identifier")
    run_id: str = Field(..., description="Correlated simulation run ID")
    record_id: str = Field(..., description="Originating telemetry record ID")
    host_id: str = Field(..., description="Affected synthetic host identifier")
    rule_id: str = Field(..., description="Matched condition-action rule identifier")
    severity: Severity = Field(..., description="Deterministic vulnerability severity")
    title: str = Field(..., min_length=1, description="Concise finding headline")
    description: str = Field(..., description="Detailed technical description")
    evidence: dict[str, Any] = Field(default_factory=dict, description="Matched percept fields")
    confidence: float = Field(1.0, ge=0.0, le=1.0, description="Deterministic confidence metric")
    integrity_flags: list[str] = Field(
        default_factory=list,
        description="Data-integrity anomaly flags",
    )
    created_at: str = Field(..., description="ISO-8601 UTC finding generation timestamp")
